draw:
var cyc = 8;
var tc = t % cyc;
var w0 = p.omega0, al = p.alpha;
var th = w0 * tc + 0.5 * al * tc * tc;
var w = w0 + al * tc;
var R = Math.min(W * 0.30, H * 0.38);
var cx = W * 0.30, cy = H * 0.52;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + R * 1.22, cy);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("theta = 0", cx + R * 0.62, cy - 6);

var k;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (k = 0; k < 4; k++) {
  var a = th + k * Math.PI / 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + R * Math.cos(a), cy - R * Math.sin(a));
  ctx.stroke();
}

var tha = Math.min(Math.abs(th), Math.PI * 2);
var end = th > 0 ? -tha : tha;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.arc(cx, cy, R * 0.42, 0, end, th > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
var mid = th > 0 ? tha / 2 : -tha / 2;
ctx.fillText("theta", cx + R * 0.55 * Math.cos(mid) - 8, cy - R * 0.55 * Math.sin(mid) + 4);

var mx = cx + R * Math.cos(th), my = cy - R * Math.sin(th);
var vlen = Math.min(Math.abs(w) * R * 0.075, R * 0.75);
var sgn = w >= 0 ? 1 : -1;
var tx = -Math.sin(th) * sgn, ty = -Math.cos(th) * sgn;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(mx, my);
ctx.lineTo(mx + tx * vlen, my + ty * vlen);
ctx.stroke();
var hx = mx + tx * vlen, hy = my + ty * vlen;
ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - tx * 7 - ty * 4, hy - ty * 7 + tx * 4);
ctx.lineTo(hx - tx * 7 + ty * 4, hy - ty * 7 - tx * 4);
ctx.closePath();
ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("v = omega r", hx + 6, hy - 4);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(mx, my, 5, 0, Math.PI * 2);
ctx.fill();

var bx = W * 0.63;
var by = H * 0.26;
var lh = Math.min(22, H * 0.13);
ctx.fillStyle = C.ink;
ctx.fillText("t     = " + tc.toFixed(2) + " s", bx, by);
ctx.fillText("omega = " + w.toFixed(2) + " rad/s", bx, by + lh);
ctx.fillText("alpha = " + al.toFixed(2) + " rad/s^2", bx, by + 2 * lh);
ctx.fillStyle = C.figure;
ctx.fillText("theta = " + th.toFixed(2) + " rad", bx, by + 3 * lh);
ctx.fillStyle = C.faint;
ctx.fillText("      = " + (th / (2 * Math.PI)).toFixed(2) + " rev", bx, by + 4 * lh);

out.note = "theta = " + th.toFixed(2) + " rad (" + (th / (2 * Math.PI)).toFixed(2) +
  " rev), omega = " + w.toFixed(2) + " rad/s at t = " + tc.toFixed(2) + " s";
